import { useCallback, useEffect, useRef, useState } from 'react';
import { workspaceService } from '../services/workspaceService';
import { adaptTableRecords } from '../adapters/tableRecordsAdapter';
import {
  buildRecordsQueryParams,
  getRecordFiltersKey,
} from '../records/adapters/recordFiltersAdapter';
import {
  applySocketRowsToTable,
  extractIsCampaignOwner,
  filterVisibleSocketLeads,
  removeUnreadLeadIds,
} from '../records/utils/socketLeadVisibility';

/**
 * Loads form field schema + lead records for a workspace table.
 */
export default function useTableRecords({
  workspaceId,
  tableId,
  formItems,
  search = '',
  page = 0,
  pageSize = 10,
  sortBy = '',
  sortType = '',
  filters = {},
  refreshToken = 0,
  currentUserId,
}) {
  const [columns, setColumns] = useState([]);
  const [rows, setRows] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [uniquePhoneCount, setUniquePhoneCount] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [formPayload, setFormPayload] = useState(null);
  const [isCampaignOwner, setIsCampaignOwner] = useState(false);
  const [unreadLeadIds, setUnreadLeadIds] = useState(() => new Set());
  const [liveAnnouncement, setLiveAnnouncement] = useState('');
  const requestIdRef = useRef(0);
  const lastQueryKeyRef = useRef('');
  const formItemsRef = useRef(formItems);
  const filtersRef = useRef(filters);
  const unreadLeadIdsRef = useRef(unreadLeadIds);
  const totalCountRef = useRef(totalCount);
  formItemsRef.current = formItems;
  filtersRef.current = filters;
  unreadLeadIdsRef.current = unreadLeadIds;
  totalCountRef.current = totalCount;

  const filtersKey = getRecordFiltersKey(filters);
  const queryKey = [
    workspaceId || '',
    tableId || '',
    search,
    page,
    pageSize,
    sortBy,
    sortType,
    filtersKey,
    refreshToken,
  ].join('|');

  const applySocketNotification = useCallback((payload) => {
    const notificationType =
      payload?.type === 'notification'
        ? payload?.notification_type
        : payload?.notification_type;

    if (!notificationType || !formPayload || columns.length === 0) {
      return;
    }

    const incoming = Array.isArray(payload?.data) ? payload.data : [payload?.data].filter(Boolean);
    const visibility = {
      currentUserId,
      isCampaignOwner,
      campaignId: workspaceId,
      formId: tableId,
    };

    const visibleIncoming = notificationType === 'delete_leads'
      ? incoming
      : filterVisibleSocketLeads(incoming, visibility);

    if (!visibleIncoming.length) return;

    const adapted = notificationType === 'delete_leads'
      ? {
        rows: visibleIncoming.map((entry) => ({
          id: entry?.id ?? entry?.lead_id ?? entry?._id ?? entry?.record_id,
          lead_id: entry?.lead_id ?? entry?.id,
        })),
      }
      : adaptTableRecords(formPayload, { list: visibleIncoming });

    const incomingRows = adapted?.rows ?? [];
    if (!incomingRows.length) return;

    setRows((prevRows) => {
      const merged = applySocketRowsToTable({
        notificationType,
        incomingRows,
        prevRows,
        prevTotalCount: totalCountRef.current,
        unreadLeadIds: unreadLeadIdsRef.current,
      });

      unreadLeadIdsRef.current = merged.unreadLeadIds;
      totalCountRef.current = merged.totalCount;
      setUnreadLeadIds(merged.unreadLeadIds);
      setTotalCount(merged.totalCount);
      if (merged.insertedCount > 0) {
        setLiveAnnouncement(
          merged.insertedCount === 1
            ? 'New lead received'
            : `${merged.insertedCount} new leads received`
        );
      }
      return merged.rows;
    });
  }, [
    columns.length,
    currentUserId,
    formPayload,
    isCampaignOwner,
    tableId,
    workspaceId,
  ]);

  const markLeadRead = useCallback((leadId) => {
    if (!leadId) return;
    setUnreadLeadIds((prev) => {
      const next = removeUnreadLeadIds(prev, [leadId]);
      unreadLeadIdsRef.current = next;
      return next;
    });
  }, []);

  const fetchRecords = useCallback(async () => {
    const requestId = requestIdRef.current + 1;
    requestIdRef.current = requestId;

    if (!workspaceId || !tableId) {
      setColumns([]);
      setRows([]);
      setTotalCount(0);
      totalCountRef.current = 0;
      setUniquePhoneCount(0);
      setError(null);
      setFormPayload(null);
      setIsCampaignOwner(false);
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const currentFilters = filtersRef.current;
      const currentFormItems = formItemsRef.current;
      const queryParams = buildRecordsQueryParams({
        workspaceId,
        tableId,
        search,
        page,
        pageSize,
        sortBy,
        sortType,
        filters: currentFilters,
      });

      const recordsPromise = workspaceService.getTableRecords(workspaceId, tableId, queryParams);

      const hasCachedFormItems = currentFormItems && (
        Array.isArray(currentFormItems)
          ? currentFormItems.length > 0
          : Object.keys(currentFormItems).length > 0
      );

      let nextFormPayload = hasCachedFormItems ? { leads_form_items: currentFormItems } : null;

      if (!nextFormPayload) {
        const formRes = await workspaceService.getLeadFormById(tableId);
        if (formRes?.status === 200 || formRes?.status === 201) {
          nextFormPayload = formRes.data;
        }
      }

      const recordsRes = await recordsPromise;

      if (recordsRes?.status !== 200 && recordsRes?.status !== 201) {
        throw new Error('Unable to load table records');
      }

      const adapted = adaptTableRecords(nextFormPayload, recordsRes.data);
      if (requestId !== requestIdRef.current) return;

      setFormPayload(nextFormPayload);
      setColumns(adapted.columns);
      setRows(adapted.rows);
      setTotalCount(adapted.totalCount);
      totalCountRef.current = adapted.totalCount;
      setUniquePhoneCount(adapted.uniquePhoneCount);
      setIsCampaignOwner(extractIsCampaignOwner(recordsRes.data));
    } catch (err) {
      if (requestId !== requestIdRef.current) return;

      setColumns([]);
      setRows([]);
      setTotalCount(0);
      totalCountRef.current = 0;
      setUniquePhoneCount(0);
      setFormPayload(null);
      setIsCampaignOwner(false);
      setError(
        err?.response?.data?.message
        || err?.message
        || 'Unable to load table records'
      );
    } finally {
      if (requestId === requestIdRef.current) {
        setIsLoading(false);
      }
    }
  }, [
    workspaceId,
    tableId,
    search,
    page,
    pageSize,
    sortBy,
    sortType,
    filtersKey,
    refreshToken,
  ]);

  useEffect(() => {
    if (lastQueryKeyRef.current === queryKey) return;
    lastQueryKeyRef.current = queryKey;
    fetchRecords();
  }, [queryKey, fetchRecords]);

  return {
    columns,
    rows,
    totalCount,
    uniquePhoneCount,
    isLoading,
    error,
    formPayload,
    unreadLeadIds,
    liveAnnouncement,
    markLeadRead,
    refetch: fetchRecords,
    applySocketNotification,
  };
}
