import React from 'react';
import CommentModal from './CommentModal';
import ViewImagesModal from '../../../../components/Leads/ViewImagesModal.tsx';
import FormDetailsModal from '../../../../components/Leads/FormDetailsModal.tsx';
import StatusLogsModal from './status-logs/StatusLogsModal';
import ManageActionModal from '../../../../components/Leads/V1/ManageActionModal.tsx';
import ModalForms from '../../../../components/Shared/Modals/index.js';
import { CallingModal } from '../../../../components/Modals/CallingModal/CallingModal.jsx';
import LeadAssignModal from './LeadAssignModal';

export default function RowActionsModals({
  rowModals,
  workspaceId,
  tableId,
  dynamicFormFields = [],
  dynamicFormGroups = [],
  onRecordUpdated,
}) {
  const {
    selectedRow,
    closeRowModal,
    isCommentOpen,
    isManageOpen,
    isFormDetailOpen,
    isStatusLogsOpen,
    isImagesOpen,
    isQuickCallOpen,
    isAssignOpen,
  } = rowModals;

  return (
    <>
      {isCommentOpen ? (
        <CommentModal
          open={isCommentOpen}
          onClose={closeRowModal}
          selectedRow={selectedRow}
          onSuccess={onRecordUpdated}
        />
      ) : null}

      {isManageOpen ? (
        <ManageActionModal
          open={isManageOpen}
          onClose={() => {
            closeRowModal();
            onRecordUpdated?.();
          }}
          lead={selectedRow}
        />
      ) : null}

      {isFormDetailOpen ? (
        <FormDetailsModal
          open={isFormDetailOpen}
          onClose={() => {
            closeRowModal();
            onRecordUpdated?.();
          }}
          selectedRow={selectedRow}
          dynamicFormFields={dynamicFormFields}
          dynamicFormGroups={dynamicFormGroups}
          currentCampaignId={workspaceId}
          currentLeadFormId={tableId}
          parentLead={null}
        />
      ) : null}

      {isStatusLogsOpen ? (
        <StatusLogsModal
          open={isStatusLogsOpen}
          onClose={closeRowModal}
          selectedRow={selectedRow}
          leadFormId={String(tableId ?? '')}
        />
      ) : null}

      {isImagesOpen ? (
        <ViewImagesModal
          open={isImagesOpen}
          onClose={closeRowModal}
          selectedRow={selectedRow}
          onSaveImage={() => {
            onRecordUpdated?.();
          }}
        />
      ) : null}

      {isQuickCallOpen ? (
        <ModalForms
          show={isQuickCallOpen}
          handleClose={closeRowModal}
          modalBody={
            <CallingModal userDetails={{ phone_number: selectedRow?.phone_number || '' }} />
          }
          modalHeader="Quick Call"
          modalId="campaign-record-calling"
          size="sm"
        />
      ) : null}

      {isAssignOpen ? (
        <LeadAssignModal
          open={isAssignOpen}
          onClose={closeRowModal}
          campaignId={workspaceId}
          selectedRow={selectedRow}
          onSuccess={onRecordUpdated}
        />
      ) : null}
    </>
  );
}
