import {
  findOptimisticOutboundIndex,
  isDuplicateLeadChatMessage,
  mergeIncomingWithOptimistic,
} from '../../utils/leadChatMessageDedup';

function phoneMatches(activePhone, incomingPhone) {
  if (!activePhone || !incomingPhone) return false;
  const cleanActive = `${activePhone}`.replace(/\D/g, '');
  const cleanIncoming = `${incomingPhone}`.replace(/\D/g, '');
  return (
    cleanActive === cleanIncoming
    || (cleanActive.length >= 10
      && cleanIncoming.length >= 10
      && cleanActive.slice(-10) === cleanIncoming.slice(-10))
  );
}

export function applyIncomingMessage(messages, incomingMessage, { activePhone, botNumber }) {
  if (!incomingMessage) return messages;

  const incoming = incomingMessage.message || incomingMessage;
  const incomingPhone = incoming?.phone_number;
  if (!phoneMatches(activePhone, incomingPhone)) return messages;

  if (botNumber && incoming?.bot_number && `${incoming.bot_number}` !== `${botNumber}`) {
    return messages;
  }

  const optimisticIndex = findOptimisticOutboundIndex(messages, incoming);
  if (optimisticIndex >= 0) {
    const next = [...messages];
    next[optimisticIndex] = mergeIncomingWithOptimistic(messages[optimisticIndex], incoming);
    return next;
  }

  if (messages.some((message) => isDuplicateLeadChatMessage(message, incoming))) {
    return messages;
  }

  return [...messages, incoming];
}

export function applyMessageStatus(messages, payload) {
  if (!payload?.w_id || !messages?.length) return messages;

  const incomingStatus = `${payload.status?.type || payload.status || ''}`.toLowerCase();
  if (!incomingStatus) return messages;

  return messages.map((message) => {
    const isMatch = message.w_id === payload.w_id || message.msg_id === payload.w_id;
    if (!isMatch) return message;
    return {
      ...message,
      w_id: message.w_id || payload.w_id,
      status: {
        type: incomingStatus,
        timestamp: payload.timestamp || message?.status?.timestamp,
      },
    };
  });
}
