import React from 'react';
import { Box, Tooltip, Typography } from '@mui/material';

export default function LeadChatMediaAttachTooltip({
  title,
  hint,
  children,
  placement = 'top',
}) {
  if (!title) {
    return children;
  }

  return (
    <Tooltip
      arrow
      placement={placement}
      describeChild
      title={
        <Box sx={{ py: 0.25, maxWidth: 220 }}>
          <Typography
            component="span"
            variant="caption"
            display="block"
            sx={{ fontWeight: 600, lineHeight: 1.35 }}
          >
            {title}
          </Typography>
          {hint ? (
            <Typography
              component="span"
              variant="caption"
              display="block"
              sx={{ opacity: 0.92, mt: 0.25, lineHeight: 1.35 }}
            >
              {hint}
            </Typography>
          ) : null}
        </Box>
      }
    >
      {children}
    </Tooltip>
  );
}
